import re

_NAME_PATTERNS = [
    re.compile(r"(?:My name is|My name's)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)", re.IGNORECASE),
    re.compile(r"(?:This is|It's|Its|I am|I'm)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)", re.IGNORECASE),
    re.compile(r"(?:name is|name's)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)", re.IGNORECASE),
]

def extract_name_regex(text: str) -> str | None:
    for pattern in _NAME_PATTERNS:
        m = pattern.search(text)
        if m:
            # Title-case the captured group to normalize any casing quirks
            return m.group(1).title()
    return None  # Signal: fall through to LLM

