step_3_merge.python_implementation:
def merge_product_results(
    regex_codes: list[str],
    llm_extras: list[str] | None
) -> list[str]:
    results = list(regex_codes)
    if llm_extras:
        for item in llm_extras:
            if item not in results:
                results.append(item)
    return results
